<?php
require __DIR__ . '/../lib/bootstrap.php';$user=auth_user();$d=input();if($_SERVER['REQUEST_METHOD']!=='POST')fail('Method not allowed',405);$action=(string)($d['action']??'start');if($action==='start'){$chat=(int)($d['chat_id']??0);$lat=(float)($d['latitude']??999);$lng=(float)($d['longitude']??999);$seconds=(int)($d['duration_seconds']??900);if(abs($lat)>90||abs($lng)>180||!in_array($seconds,[900,3600,28800],true))fail('Invalid location or duration');$st=db()->prepare('INSERT INTO live_locations(chat_id,user_id,latitude,longitude,started_at,last_update_at,expires_at,active) VALUES(?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP(),UTC_TIMESTAMP()+INTERVAL ? SECOND,1)');$st->execute([$chat,$user['id'],$lat,$lng,$seconds]);out(['location_share_id'=>(int)db()->lastInsertId()],201);}if($action==='stop'){$id=(int)($d['location_share_id']??0);$st=db()->prepare('UPDATE live_locations SET active=0,stopped_at=UTC_TIMESTAMP() WHERE id=? AND user_id=?');$st->execute([$id,$user['id']]);out(['message'=>'Live location stopped']);}fail('Invalid action');
